  analysis: "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa-bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb",
  operation: "flowmap",
  from: { name: "submit" },
  all: true
});

// Extract the relevant information
const flowMap = result.flowMap;

// Check if we have a complete map
const isComplete = flowMap.complete === true || flowMap.complete === "true";

// Find the exit call for rebate parameter
let exitCall = null;
let sinkExpression = null;
let controlAssumption = null;
let dataAssumption = null;
let behaviorVerified = false;

// Look for the trace of rebate to argument 1 of save
for (const node of flowMap.nodes) {
  if (node.name === "save" && node.argument === 1) {
    exitCall = node.name;
    sinkExpression = node.expression;

    // Check assumptions
    controlAssumption = node.controlAssumption;
    dataAssumption = node.dataAssumption;

    // Check behavior verification
    behaviorVerified = node.behaviorVerified || false;
  }
}

// If no specific node found, look for edges related to rebate
if (!exitCall) {
  for (const edge of flowMap.edges) {
    if (edge.from.name === "submit" && edge.to.name === "save") {
      exitCall = edge.to.name;
      sinkExpression = edge.expression;

      // Check assumptions on the edge
      controlAssumption = edge.controlAssumption;
      dataAssumption = edge.dataAssumption;

      behaviorVerified = edge.behaviorVerified || false;
    }
  }
}

// Prepare the result
const evidenceViews = [];
if (flowMap.views) {
  for (const view of flowMap.views) {
    evidenceViews.push({
      name: view.name,
      link: view.link
    });
  }
}

const finalResult = {
  entry: "submit",
  exitCall: exitCall || null,
  sinkExpression: sinkExpression || null,
  controlAssumption: controlAssumption || null,
  dataAssumption: dataAssumption || null,
  behaviorVerified: behaviorVerified,
  mapComplete: isComplete,
  evidenceViews: evidenceViews
};

// Print the result
text("Final Result:", JSON.stringify(finalResult, null, 2));

// Return the result
return finalResult;

